sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float kind;
uniform float interp;
uniform float rotation;
uniform float radiusScale;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 ctr = center * size;
    float maxR = length(size) * 0.5;
    float2 d = coord - ctr;
    float a = atan(d.y, d.x) + radians(rotation);
    float2 src = float2((a / 6.2831853 + 0.5) * size.x, length(d) / maxR * size.y * radiusScale);
    if (kind > 0.5) {
        float pa = coord.x / size.x * 6.2831853 - 3.1415927 + radians(rotation);
        float pr = coord.y / size.y * maxR * radiusScale;
        src = ctr + float2(cos(pa), sin(pa)) * pr;
    }
    return fin(c, tex(mix(coord, src, interp)), opacity);
}
